import React, { useState, useEffect } from "react";
import styled from "styled-components";
import { useParams, useNavigate } from "react-router-dom";
import axios from "../utils/api";

const DashboardPage = () => {
  const { registrationNumber } = useParams();
  const navigate = useNavigate();

  const [ownerName, setOwnerName] = useState("Thangavelu"); // Default owner name
  const [ownerPhone, setOwnerPhone] = useState("9443769338"); // Default owner phone

  useEffect(() => {
    const fetchLorryDetails = async () => {
      try {
        const response = await axios.get(`/lorry/${registrationNumber}`);
        setOwnerName(response.data.owner_phone || "Unknown Owner");
        setOwnerPhone(response.data.owner_phone || "Unknown Phone");
      } catch (error) {
        console.error("Error fetching lorry details:", error.message);
      }
    };
    fetchLorryDetails();
  }, [registrationNumber]);

  const handleNavigation = (path) => {
    navigate(path, { state: { registrationNumber } });
  };

  return (
    <Container>
      <Header>
        <HeaderItem>{registrationNumber}</HeaderItem>
        <HeaderItem>{ownerName}</HeaderItem>
        <HeaderItem>{ownerPhone}</HeaderItem>
      </Header>

      <Navigation>
        <NavButton onClick={() => handleNavigation("/employee")}>
          Employee
        </NavButton>
        <NavButton onClick={() => handleNavigation("/fuel")}>
          Fuel Details
        </NavButton>
        <NavButton onClick={() => handleNavigation("/point-details")}>
          Point Details
        </NavButton>
      </Navigation>
    </Container>
  );
};

export default DashboardPage;

// Styled Components
const Container = styled.div`
  font-family: "Arial", sans-serif;
  display: flex;
  flex-direction: column;
  height: 100vh;
  background-color: #f9f9f9;
`;

const Header = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 30px;
  background-color: #00796b;
  color: white;
  font-size: 18px;
  font-weight: bold;
`;

const HeaderItem = styled.div`
  flex: 1;
  text-align: center;

  &:first-child {
    text-align: left;
  }

  &:last-child {
    text-align: right;
  }
`;

const Navigation = styled.div`
  flex: 1;
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding: 20px;
  background-color: white;
`;

const NavButton = styled.button`
  padding: 15px 25px;
  font-size: 16px;
  background-color: #00796b;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.3s ease;

  &:hover {
    background-color: #004d40;
    transform: translateY(-3px);
  }

  &:active {
    transform: translateY(1px);
  }
`;
